const $=(s,r=document)=>r.querySelector(s), $$=(s,r=document)=>[...r.querySelectorAll(s)];
const state={count:5,file:null,frames:[],sourceName:"",googleTabs:[],extensionReady:false,bridgeProgress:0,bridgeResults:new Set,bridgeExpected:0,jobId:0};
const searchProviders=[{name:"Google Lens",href:"https://lens.google.com/"},{name:"Yandex",href:"https://yandex.com/images/"},{name:"Bing",href:"https://www.bing.com/visualsearch"},{name:"TinEye",href:"https://tineye.com/"}];
function showToast(message){const t=$("#toast");t.textContent=message;t.classList.add("visible");clearTimeout(showToast.timer);showToast.timer=setTimeout(()=>t.classList.remove("visible"),3400)}
function setStatus(message,visible=true,busy=true){const s=$("#status");$("#statusText").textContent=message;s.classList.toggle("visible",visible);$(".spinner",s).style.display=busy?"block":"none"}
function setCount(value){state.count=Math.max(2,Math.min(30,Number(value)||5));$("#countInput").value=state.count;$$('.count-btn').forEach(b=>b.classList.toggle('active',Number(b.dataset.count)===state.count))}
$$('.count-btn').forEach(b=>b.addEventListener('click',()=>setCount(b.dataset.count)));$("#countMinus").addEventListener('click',()=>setCount(state.count-1));$("#countPlus").addEventListener('click',()=>setCount(state.count+1));$("#countInput").addEventListener('change',e=>setCount(e.target.value));
function openModal(id){$("#"+id).classList.add('visible')}function closeModal(id){$("#"+id).classList.remove('visible')}
$$('[data-close]').forEach(b=>b.addEventListener('click',()=>closeModal(b.dataset.close)));$$('.modal-backdrop').forEach(b=>b.addEventListener('click',e=>{if(e.target===b)b.classList.remove('visible')}));document.addEventListener('keydown',e=>{if(e.key==='Escape')$$('.modal-backdrop.visible').forEach(m=>m.classList.remove('visible'))});
const savedTheme=localStorage.getItem('rvs-theme');if(savedTheme)document.documentElement.dataset.theme=savedTheme;$("#themeToggle").addEventListener('click',()=>{const theme=document.documentElement.dataset.theme==='dark'?'light':'dark';document.documentElement.dataset.theme=theme;localStorage.setItem('rvs-theme',theme);$("#themeToggle").textContent=theme==='dark'?'☾':'☼'});if(savedTheme==='dark')$("#themeToggle").textContent='☾';
const fileInput=$("#fileInput"),dropzone=$("#dropzone");$("#chooseFile").addEventListener('click',e=>{e.stopPropagation();fileInput.click()});dropzone.addEventListener('click',e=>{if(!e.target.closest('button')&&!e.target.closest('.drop-action'))fileInput.click()});dropzone.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();fileInput.click()}});fileInput.addEventListener('change',e=>{if(e.target.files[0])handleFile(e.target.files[0])});['dragenter','dragover'].forEach(t=>dropzone.addEventListener(t,e=>{e.preventDefault();dropzone.classList.add('dragging')}));['dragleave','drop'].forEach(t=>dropzone.addEventListener(t,e=>{e.preventDefault();dropzone.classList.remove('dragging')}));dropzone.addEventListener('drop',e=>{const f=e.dataTransfer.files[0];if(f)handleFile(f)});$("#demoBtn").addEventListener('click',e=>{e.stopPropagation();loadDemo()});
function waitEvent(target,event){return new Promise((resolve,reject)=>{const done=()=>{cleanup();resolve()};const fail=e=>{cleanup();reject(e)};const cleanup=()=>{target.removeEventListener(event,done);target.removeEventListener('error',fail)};target.addEventListener(event,done,{once:true});target.addEventListener('error',fail,{once:true})})}
function imageFrame(file){return new Promise((resolve,reject)=>{const img=new Image();img.onload=()=>{const c=document.createElement('canvas'),scale=Math.min(1,1280/Math.max(img.width,img.height));c.width=Math.max(1,Math.round(img.width*scale));c.height=Math.max(1,Math.round(img.height*scale));c.getContext('2d').drawImage(img,0,0,c.width,c.height);URL.revokeObjectURL(img.src);resolve({dataUrl:c.toDataURL('image/jpeg',.9),time:0})};img.onerror=reject;img.src=URL.createObjectURL(file)})}
async function extractVideoFrames(file,count){const video=document.createElement('video');video.muted=true;video.playsInline=true;video.preload='metadata';video.src=URL.createObjectURL(file);await waitEvent(video,'loadedmetadata');await waitEvent(video,'loadeddata').catch(()=>{});const duration=Number.isFinite(video.duration)&&video.duration>0?video.duration:1,c=document.createElement('canvas'),ratio=video.videoHeight&&video.videoWidth?video.videoHeight/video.videoWidth:1.45;c.width=720;c.height=Math.round(c.width*ratio);const ctx=c.getContext('2d'),frames=[];for(let i=0;i<count;i++){const time=count===1?0:duration*i/(count-1);video.currentTime=Math.min(time,Math.max(0,duration-.05));await waitEvent(video,'seeked').catch(()=>{});ctx.drawImage(video,0,0,c.width,c.height);frames.push({dataUrl:c.toDataURL('image/jpeg',.88),time})}URL.revokeObjectURL(video.src);return frames}
async function handleFile(file){if(!file.type.startsWith('video/')&&!file.type.startsWith('image/'))return showToast('请选择 MP4、MOV、WEBM 或常见图片文件');state.file=file;state.sourceName=file.name;setStatus('正在本地提取关键帧…');try{state.frames=file.type.startsWith('image/')?[await imageFrame(file)]:await extractVideoFrames(file,state.count);renderResults();setStatus(`已提取 ${state.frames.length} 张图片`,true,false);showToast('处理完成：原始文件没有上传到本地应用服务器')}catch(e){console.error(e);setStatus('处理失败，请换一个文件重试',true,false);showToast('浏览器无法读取这个文件')}}
function demoFrame(index){const c=document.createElement('canvas');c.width=720;c.height=960;const x=c.getContext('2d'),hue=198+index*13,g=x.createLinearGradient(0,0,c.width,c.height);g.addColorStop(0,`hsl(${hue},75%,24%)`);g.addColorStop(.52,`hsl(${hue+35},76%,54%)`);g.addColorStop(1,`hsl(${hue+58},88%,76%)`);x.fillStyle=g;x.fillRect(0,0,c.width,c.height);x.globalAlpha=.22;for(let n=0;n<8;n++){x.fillStyle=n%2?'#fff':'#0c2340';x.beginPath();x.arc(50+n*110,150+(index*47+n*35)%600,35+n*9,0,Math.PI*2);x.fill()}x.globalAlpha=1;x.fillStyle='rgba(0,0,0,.26)';x.fillRect(28,28,258,54);x.fillStyle='#fff';x.font='700 24px system-ui';x.fillText('DEMO FRAME',48,63);x.font='600 26px ui-monospace';x.fillText(`00:${String(index*11%60).padStart(2,'0')}.0`,38,915);x.font='700 34px system-ui';x.fillText('LOCAL VIDEO SEARCH',38,865);return{dataUrl:c.toDataURL('image/jpeg',.9),time:index*1.1}}
function loadDemo(){state.file=null;state.sourceName='演示视频';state.frames=Array.from({length:state.count},(_,i)=>demoFrame(i));renderResults();setStatus(`已加载 ${state.frames.length} 张演示图片`,true,false);showToast('这是本地演示数据，你可以直接测试卡片操作')}
function timecode(seconds){const mins=Math.floor(seconds/60),secs=Math.floor(seconds%60),tenths=Math.floor(seconds%1*10);return`${String(mins).padStart(2,'0')}:${String(secs).padStart(2,'0')}.${tenths}`}
function renderResults(){$("#results").classList.add('visible');$("#frameCountLabel").textContent=`${state.frames.length} extracted`;const grid=$("#framesGrid");grid.innerHTML='';state.frames.forEach((frame,index)=>{const card=document.createElement('article');card.className='frame-card';card.dataset.index=index;card.innerHTML=`<div class="frame-image-wrap"><img class="frame-image" src="${frame.dataUrl}" alt="第 ${index+1} 张关键帧" loading="lazy"><div class="frame-overlay"><button class="check" data-action="toggle" aria-label="选择第 ${index+1} 张图片">✓</button><div class="frame-tools"><button class="mini-btn" data-action="preview" title="预览">⌗</button><button class="mini-btn" data-action="download" title="下载">⇩</button></div></div><span class="timecode">${timecode(frame.time)}</span></div><div class="frame-meta">${searchProviders.map(p=>`<a class="search-link" href="${p.href}" target="_blank" rel="noopener">${p.name}<small>↗</small></a>`).join('')}</div>`;grid.appendChild(card)});$$('[data-action]',grid).forEach(b=>b.addEventListener('click',frameAction))}
function frameAction(e){const btn=e.currentTarget,card=btn.closest('.frame-card'),frame=state.frames[Number(card.dataset.index)],action=btn.dataset.action;if(action==='toggle'){btn.textContent=btn.textContent==='✓'?'':'✓';btn.style.background=btn.textContent?'#1570ef':'rgba(255,255,255,.92)';btn.style.color=btn.textContent?'#fff':'#172033'}if(action==='preview'){$("#lightboxImage").src=frame.dataUrl;$("#lightboxCaption").textContent=`${state.sourceName||'关键帧'} · ${timecode(frame.time)}`;openModal('lightbox')}if(action==='download'){const a=document.createElement('a');a.href=frame.dataUrl;a.download=`reverse-frame-${String(Number(card.dataset.index)+1).padStart(2,'0')}.jpg`;a.click();showToast('关键帧已下载')}}
$("#urlInput").addEventListener('input',e=>$("#fetchBtn").disabled=!e.target.value.trim());$("#fetchBtn").addEventListener('click',()=>{const url=$("#urlInput").value.trim();if(!url)return;state.sourceName=url;loadDemo();showToast('链接已记录。由于跨域限制，本地版用演示帧展示工作流；你也可以先下载视频再上传。')});
$("#saveSearchBtn").addEventListener('click',()=>{if(!state.frames.length)return;const saved=JSON.parse(localStorage.getItem('rvs-history')||'[]');saved.unshift({name:state.sourceName||'未命名搜索',count:state.frames.length,at:new Date().toLocaleString('zh-CN')});localStorage.setItem('rvs-history',JSON.stringify(saved.slice(0,12)));renderHistory();showToast('本次搜索已保存到当前浏览器')});function escapeHtml(t){return t.replace(/[&<>"']/g,ch=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]))}function renderHistory(){const saved=JSON.parse(localStorage.getItem('rvs-history')||'[]');$("#historyCount").textContent=`${saved.length} saved`;$("#historyContent").innerHTML=saved.length?saved.map(i=>`<div class="history-item"><span><strong>${escapeHtml(i.name)}</strong><br><span class="muted">${i.count} 帧 · ${i.at}</span></span><span>本地</span></div>`).join(''):'暂无保存记录。完成一次搜索后，可以保存本次搜索。'}renderHistory();
function clearResults(){cancelBridgeSearch();state.jobId++;state.frames=[];state.googleTabs=[];state.bridgeProgress=0;state.bridgeResults.clear();state.bridgeExpected=0;$("#results").classList.remove('visible');$("#framesGrid").innerHTML='';setStatus('',false)}$("#newSearchBtn").addEventListener('click',()=>{clearResults();$("#dropzone").scrollIntoView({behavior:'smooth',block:'center'})});$("#clearResultsBtn").addEventListener('click',clearResults);
$("#audioBtn").addEventListener('click',async()=>{if(!state.file||!state.file.type.startsWith('video/'))return showToast('请先上传视频文件；演示帧没有音轨');setStatus('正在本地读取音轨…');try{const Ctx=window.AudioContext||window.webkitAudioContext;if(!Ctx)throw Error('AudioContext unavailable');const audio=await new Ctx().decodeAudioData(await state.file.arrayBuffer()),wav=encodeWav(audio),blob=new Blob([wav],{type:'audio/wav'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='reverse-video-audio.wav';a.click();setStatus('音频已导出为 WAV',true,false);showToast('音频已下载')}catch(e){console.error(e);setStatus('当前视频无法导出音频',true,false);showToast('浏览器或视频编码不支持音频解码')}});
function encodeWav(buffer){const channels=buffer.numberOfChannels,sampleRate=buffer.sampleRate,length=buffer.length*channels*2+44,out=new ArrayBuffer(length),view=new DataView(out),write=(o,s)=>{[...s].forEach((c,i)=>view.setUint8(o+i,c.charCodeAt(0)))};write(0,'RIFF');view.setUint32(4,length-8,true);write(8,'WAVE');write(12,'fmt ');view.setUint32(16,16,true);view.setUint16(20,1,true);view.setUint16(22,channels,true);view.setUint32(24,sampleRate,true);view.setUint32(28,sampleRate*channels*2,true);view.setUint16(32,channels*2,true);view.setUint16(34,16,true);write(36,'data');view.setUint32(40,length-44,true);let o=44;for(let i=0;i<buffer.length;i++)for(let ch=0;ch<channels;ch++){const s=buffer.getChannelData(ch)[i]||0;view.setInt16(o,Math.max(-1,Math.min(1,s))*0x7fff,true);o+=2}return out}
function compactFrameDataUrl(dataUrl){return new Promise(resolve=>{const img=new Image();img.onload=()=>{const max=140,scale=Math.min(1,max/Math.max(img.naturalWidth||img.width,img.naturalHeight||img.height));const c=document.createElement('canvas');c.width=Math.max(1,Math.round((img.naturalWidth||img.width)*scale));c.height=Math.max(1,Math.round((img.naturalHeight||img.height)*scale));c.getContext('2d').drawImage(img,0,0,c.width,c.height);resolve(c.toDataURL('image/jpeg',.24))};img.onerror=()=>resolve(dataUrl);img.src=dataUrl})}
function ensureGooglePanel(){let panel=$("#googleAutoPanel");if(panel)return panel;panel=document.createElement('div');panel.id='googleAutoPanel';panel.className='google-auto-panel';panel.innerHTML='<div><strong>自动 Google Lens 搜索</strong><p id="googleAutoStatus">安装 Google Lens Bridge 后，可把抽取的帧直接上传到 Google。</p></div><button class="primary-btn" id="googleAutoBtn" type="button">自动搜索全部帧</button>';$("#framesGrid").after(panel);$("#googleAutoBtn").addEventListener('click',()=>autoSearchGoogle());return panel}
setInterval(()=>{if(!state.frames.length)state.googleTabs=[];else if($("#results")?.classList.contains('visible')&&!state.googleTabs.length&&!state.bridgeExpected&&state.extensionReady)autoSearchGoogle()},700);
setInterval(()=>{$$('.search-link').forEach(link=>{if(!link.querySelector('.result-count')){const badge=document.createElement('em');badge.className='result-count';badge.textContent='命中：—';link.appendChild(badge);link.addEventListener('click',()=>{badge.textContent='已提交';badge.dataset.submitted='true'},{once:true})}})},700);
window.addEventListener('message',event=>{if(event.source!==window||event.data?.source!=='rvs-lens-bridge')return;if(event.data.type==='ready'){state.extensionReady=true;const status=$("#googleAutoStatus");if(status)status.textContent='Google Lens Bridge 已连接，抽帧后可自动上传文件。'}if(event.data.type==='status'){const i=Number(event.data.index),card=$(`.frame-card[data-index="${i}"]`),meta=card?.querySelector('.frame-meta');if(event.data.status==='results'||event.data.status==='error')state.bridgeResults.add(i);state.bridgeProgress=Math.max(state.bridgeProgress,i+1);if(meta){const tag=meta.querySelector('.google-status')||document.createElement('span');tag.className='google-status';tag.textContent=event.data.status==='opened'?'已提交到 Google Lens':event.data.status==='results'?'已查询':`上传失败${event.data.error?`：${event.data.error}`:''}`;if(!tag.parentNode)meta.appendChild(tag)}const status=$("#googleAutoStatus");if(status){if(event.data.status==='opened')status.textContent=`已提交第 ${i+1}/${state.frames.length} 帧，等待 Google Lens 返回…`;else if(event.data.status==='error')status.textContent=`第 ${i+1} 帧处理失败：${event.data.error||'请检查扩展权限'}`;else status.textContent=`Google Lens 已返回第 ${i+1} 帧结果，已完成 ${state.bridgeResults.size}/${state.bridgeExpected||state.frames.length} 帧。`}if(state.bridgeExpected&&state.bridgeResults.size>=state.bridgeExpected){state.googleTabs=[];const button=$("#googleAutoBtn");if(button)button.disabled=false;if(status&&state.bridgeExpected>1)status.textContent=`Google Lens 查询完成：已返回 ${state.bridgeResults.size} 帧结果。`}}});
async function autoSearchGoogle(){if(!state.frames.length)return showToast('请先抽取关键帧');const panel=ensureGooglePanel(),status=$("#googleAutoStatus"),button=$("#googleAutoBtn");if(state.googleTabs.length)return showToast('当前 Google 搜索仍在进行中，请等待结果');if(!state.extensionReady){status.innerHTML='未检测到 Google Lens Bridge。<a href="extension-install.html" target="_blank">查看安装说明并启用自动上传 ↗</a>';return showToast('请先安装并启用 Google Lens Bridge 扩展')}button.disabled=true;state.bridgeProgress=0;state.bridgeResults.clear();state.bridgeExpected=state.frames.length;state.googleTabs=[{pending:true}];status.textContent='正在把关键帧交给 Google Lens Bridge…';window.postMessage({source:'rvs-local',type:'search-frames',frames:state.frames.map(frame=>frame.dataUrl)},'*')}
setTimeout(()=>window.postMessage({source:'rvs-local',type:'ping'},'*'),250);
document.addEventListener('click',event=>{const link=event.target.closest?.('.search-link');if(!link||!/^Google Lens$/i.test(link.firstChild?.textContent?.trim()||link.textContent.trim().replace(/命中：.*$/,'')))return;const card=link.closest('.frame-card'),index=Number(card?.dataset.index);if(!Number.isInteger(index)||!state.frames[index])return;event.preventDefault();if(!state.extensionReady){ensureGooglePanel();const status=$("#googleAutoStatus");if(status)status.innerHTML='未检测到 Google Lens Bridge。<a href="extension-install.html" target="_blank">查看安装说明并启用自动上传 ↗</a>';return showToast('请先安装 Google Lens Bridge 扩展')}if(state.googleTabs.length)return showToast('当前 Google 搜索仍在进行中，请等待结果');state.bridgeProgress=0;state.bridgeResults.clear();state.bridgeExpected=1;state.googleTabs=[{pending:true}];const badge=link.querySelector('.result-count');if(badge)badge.textContent='正在上传';window.postMessage({source:'rvs-local',type:'search-frames',baseIndex:index,frames:[state.frames[index].dataUrl]},'*')});
fileInput.addEventListener('click',()=>{fileInput.value=''});
function cancelBridgeSearch(){if(state.extensionReady)window.postMessage({source:'rvs-local',type:'cancel-search'},'*')}
async function handleFile(file){if(!file.type.startsWith('video/')&&!file.type.startsWith('image/'))return showToast('请选择 MP4、MOV、WEBM 或常见图片文件');cancelBridgeSearch();const job=++state.jobId;state.file=file;state.sourceName=file.name;state.frames=[];state.googleTabs=[];state.bridgeProgress=0;state.bridgeResults.clear();state.bridgeExpected=0;$("#results").classList.remove('visible');$("#framesGrid").innerHTML='';setStatus('正在本地提取关键帧…');try{const frames=file.type.startsWith('image/')?[await imageFrame(file)]:await extractVideoFrames(file,state.count);if(job!==state.jobId)return;state.frames=frames;renderResults();setStatus(`已提取 ${state.frames.length} 张图片`,true,false);showToast(`已载入 ${file.name}，可以开始新的搜索`)}catch(e){if(job!==state.jobId)return;console.error(e);setStatus('处理失败，请换一个文件重试',true,false);showToast('浏览器无法读取这个文件')}}
function loadDemo(){cancelBridgeSearch();state.jobId++;state.file=null;state.sourceName='演示视频';state.frames=Array.from({length:state.count},(_,i)=>demoFrame(i));state.googleTabs=[];state.bridgeProgress=0;state.bridgeResults.clear();state.bridgeExpected=0;renderResults();setStatus(`已加载 ${state.frames.length} 张演示图片`,true,false);showToast('这是本地演示数据，你可以直接测试卡片操作')}
function showGoogleResults(index,payload){const card=$(`.frame-card[data-index="${index}"]`);if(!card)return;const meta=card.querySelector('.frame-meta');let badge=meta?.querySelector('.google-status');if(meta&&!badge){badge=document.createElement('span');badge.className='google-status';meta.appendChild(badge)}if(badge)badge.textContent='已查询';const link=meta?.querySelector('.search-link');const count=Number(payload?.count)||0;let countBadge=link?.querySelector('.result-count');if(link&&!countBadge){countBadge=document.createElement('em');countBadge.className='result-count';link.appendChild(countBadge)}if(countBadge)countBadge.textContent=`命中：${count}`;let box=meta?.querySelector('.google-results');if(!box){box=document.createElement('div');box.className='google-results';meta?.appendChild(box)}box.innerHTML='';const title=document.createElement('strong');title.textContent=`Google Lens 候选：${count}`;box.appendChild(title);if(payload?.url){const page=document.createElement('a');page.href=payload.url;page.target='_blank';page.rel='noopener';page.textContent='打开 Google Lens 结果页 ↗';box.appendChild(page)}if(!count&&payload?.excerpt){const excerpt=document.createElement('p');excerpt.textContent=String(payload.excerpt).slice(0,320);box.appendChild(excerpt)}(payload?.links||[]).slice(0,5).forEach(item=>{const a=document.createElement('a');a.href=item.href;a.target='_blank';a.rel='noopener';a.textContent=item.text||item.href;box.appendChild(a)})}
window.addEventListener('message',event=>{if(event.source!==window||event.data?.source!=='rvs-lens-bridge'||event.data.type!=='status'||event.data.status!=='results')return;showGoogleResults(Number(event.data.index),event.data.results||{});const status=$("#googleAutoStatus");if(status)status.textContent=`Google Lens 已返回第 ${Number(event.data.index)+1} 帧的 ${Number(event.data.results?.count)||0} 个候选链接。`});
